    let avg = salaries.reduce(0, +) / Double(salaries.count)
    let avgStr = String(format: "%.2f", avg)
    let parts = avgStr.components(separatedBy: ".")
    let intPart = Int(parts[0]) ?? 0
    let formattedInt = formatWithCommas(intPart)
    print("  \(dept): $\(formattedInt).\(parts[1])")
