    FileHandle.standardError.write("Cannot read file\n".data(using: .utf8)!)
    exit(1)
}

let lines = content.components(separatedBy: "\n").filter { !$0.isEmpty }

var levelCounts: [String: Int] = [:]
var errorComponentCounts: [String: Int] = [:]
var errorMessages: Set<String> = []
var hourCounts: [String: Int] = [:]

let pattern = "^\\[(\\d{4}-\\d{2}-\\d{2} (\\d{2}):\\d{2}:\\d{2})\\] (\\w+) \\(([^)]+)\\) - (.+)$"
guard let regex = try? NSRegularExpression(pattern: pattern) else {
    FileHandle.standardError.write("Bad regex\n".data(using: .utf8)!)
    exit(1)
}

for line in lines {
    let range = NSRange(line.startIndex..<line.endIndex, in: line)
    guard let match = regex.firstMatch(in: line, options: [], range: range),
          match.numberOfRanges == 6 else { continue }

    let hour = (line as NSString).substring(with: match.range(at: 2))
    let level = (line as NSString).substring(with: match.range(at: 3))
    let component = (line as NSString).substring(with: match.range(at: 4))
    let message = (line as NSString).substring(with: match.range(at: 5))

    levelCounts[level, default: 0] += 1
    hourCounts[hour, default: 0] += 1

    if level == "ERROR" {
        errorComponentCounts[component, default: 0] += 1
        errorMessages.insert(message)
    }
}

var out = ""
out += "=== Log Analysis ===\n"
out += "\n"
out += "Entries by Level:\n"
for level in levelCounts.keys.sorted() {
    out += "  \(level): \(levelCounts[level]!)\n"
}
out += "\n"

if let (comp, count) = errorComponentCounts.max(by: { $0.value < $1.value }) {
    out += "Component with Most Errors: \(comp) (\(count) errors)\n"
}
out += "\n"

out += "Unique Error Messages:\n"
for msg in errorMessages.sorted() {
    out += "  - \(msg)\n"
}
out += "\n"

if let (hour, count) = hourCounts.max(by: { $0.value < $1.value }) {
    out += "Busiest Hour: \(hour):00 (\(count) entries)\n"
}

print(out, terminator: "")

