use std::collections::HashMap;
use std::fs;

fn format_commas_int(n: i64) -> String {
    let neg = n < 0;
    let s = if neg { (n as u64).wrapping_neg().to_string() } else { n.to_string() };
    let bytes: Vec<char> = s.chars().collect();
    let len = bytes.len();
    let mut result = String::new();
    for (i, c) in bytes.iter().enumerate() {
        if i > 0 && (len - i) % 3 == 0 {
            result.push(',');
        }
        result.push(*c);
    }
    if neg {
        result.insert(0, '-');
    }
    result
}

fn format_commas_decimal(n: f64) -> String {
    let int_part = n as i64;
    let dec_part = ((n - int_part as f64) * 100.0).round() as i64;
    let int_str = format_commas_int(int_part);
    let dec_str = format!("{:02}", dec_part);
    format!("{}.{}", int_str, dec_str)
}

fn main() {
    let path = "<tmp>";
    let content = fs::read_to_string(path).expect("Failed to read CSV file");

    let mut lines = content.lines();
    let _header = lines.next();

    let mut dept_salaries: HashMap<String, f64> = HashMap::new();
    let mut dept_counts: HashMap<String, usize> = HashMap::new();
    let mut highest_salary: f64 = 0.0;
    let mut highest_name: String = String::new();
    let mut total_budget: f64 = 0.0;

    for line in lines {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        let fields: Vec<&str> = line.split(',').collect();
        if fields.len() < 6 {
            continue;
        }
        let name = fields[1].trim().to_string();
        let department = fields[2].trim().to_string();
        let salary: f64 = fields[3].trim().parse().unwrap_or(0.0);

        *dept_salaries.entry(department.clone()).or_insert(0.0) += salary;
        *dept_counts.entry(department.clone()).or_insert(0) += 1;

        if salary > highest_salary {
            highest_salary = salary;
            highest_name = name;
        }

        total_budget += salary;
    }

    let mut depts: Vec<String> = dept_counts.keys().cloned().collect();
    depts.sort();

    println!("=== Salary Report ===");
    println!();
    println!("Average Salary by Department:");
    for dept in &depts {
        let avg = dept_salaries[dept] / dept_counts[dept] as f64;
        println!("  {}: ${}", dept, format_commas_decimal(avg));
    }
    println!();
    println!("Highest Paid: {} (${})", highest_name, format_commas_int(highest_salary as i64));
    println!();
    println!("Departments with >2 employees:");
    for dept in &depts {
        let count = dept_counts[dept];
        if count > 2 {
            println!("  {} ({} employees)", dept, count);
        }
    }
    println!();
    println!("Total Budget: ${}", format_commas_int(total_budget as i64));
}

