    int count;
} Dept;

static void format_comma_int(long val, char *buf) {
    char tmp[32];
    if (val < 0) {
        buf[0] = '-';
        val = -val;
        sprintf(tmp, "%ld", val);
    } else {
        sprintf(tmp, "%ld", val);
    }
    int len = (int)strlen(tmp);
    int pos = (val < 0) ? 1 : 0;
    for (int i = 0; i < len; i++) {
        if (i > 0 && (len - i) % 3 == 0) {
            buf[pos++] = ',';
        }
        buf[pos++] = tmp[i];
    }
    buf[pos] = '\0';
}

static void format_comma_float2(double val, char *buf) {
    long intpart = (long)val;
    int fracpart = (int)((val - (double)intpart) * 100.0 + 0.5);
    if (fracpart >= 100) {
        intpart++;
        fracpart -= 100;
    }
    if (fracpart < 0) {
        fracpart = 0;
    }
    char ibuf[32];
    format_comma_int(intpart, ibuf);
    sprintf(buf, "%s.%02d", ibuf, fracpart);
}

