        line[strcspn(line, "\r\n")] = '\0';
        if (strlen(line) == 0) continue;

        emp = (Employee *)realloc(emp, (size_t)(n + 1) * sizeof(Employee));
        if (!emp) {
            fclose(f);
            return 1;
        }

        char *saveptr = NULL;
        char *tok;

        tok = strtok_r(line, ",", &saveptr); /* employee_id */
        (void)tok;
        tok = strtok_r(NULL, ",", &saveptr); /* name */
        if (tok) {
            strncpy(emp[n].name, tok, MAX_NAME - 1);
            emp[n].name[MAX_NAME - 1] = '\0';
        } else {
            emp[n].name[0] = '\0';
        }
        tok = strtok_r(NULL, ",", &saveptr); /* department */
        if (tok) {
            strncpy(emp[n].department, tok, MAX_NAME - 1);
            emp[n].department[MAX_NAME - 1] = '\0';
        } else {
            emp[n].department[0] = '\0';
        }
        tok = strtok_r(NULL, ",", &saveptr); /* salary */
        emp[n].salary = tok ? atof(tok) : 0.0;
        /* start_date, rating - not needed */

        n++;
    }
    fclose(f);

    if (n == 0) {
        printf("=== Salary Report ===\n\nAverage Salary by Department:\n\nHighest Paid: \n\nDepartments with >2 employees:\n\nTotal Budget: $0\n");
        return 0;
