            depts[nd].total = emp[i].salary;
            depts[nd].count = 1;
            nd++;
        }
    }

    /* Sort departments alphabetically (bubble sort) */
    for (int i = 0; i < nd - 1; i++) {
        for (int j = i + 1; j < nd; j++) {
            if (strcmp(depts[i].name, depts[j].name) > 0) {
                Dept tmp = depts[i];
                depts[i] = depts[j];
                depts[j] = tmp;
            }
        }
    }

    /* Find highest paid */
    int max_idx = 0;
    for (int i = 1; i < n; i++) {
        if (emp[i].salary > emp[max_idx].salary) max_idx = i;
    }

    /* Total budget */
    double total_budget = 0.0;
    for (int i = 0; i < n; i++) total_budget += emp[i].salary;

    /* Output */
