        printf("  %s: $%s\n", depts[i].name, fbuf);
    }
    printf("\n");

    char hbuf[32];
    format_comma_int((long)emp[max_idx].salary, hbuf);
    printf("Highest Paid: %s ($%s)\n", emp[max_idx].name, hbuf);
    printf("\n");

    printf("Departments with >2 employees:\n");
    for (int i = 0; i < nd; i++) {
        if (depts[i].count > 2) {
            printf("  %s (%d employees)\n", depts[i].name, depts[i].count);
        }
    }
    printf("\n");

    char tbuf[32];
    format_comma_int((long)total_budget, tbuf);
    printf("Total Budget: $%s\n", tbuf);

    free(emp);
    free(depts);
    return 0;
