import * as fs from 'fs';

interface Edge {
    from: string;
    to: string;
    weight: number;
}

interface GraphData {
    nodes: string[];
    edges: Edge[];
}

function main(): void {
    const filePath = '<tmp>';
    const raw = fs.readFileSync(filePath, 'utf-8');
    const data: GraphData = JSON.parse(raw);

    const nodes: string[] = data.nodes;
    const edges: Edge[] = data.edges;

    // Build adjacency list (undirected)
    const adj: Map<string, Array<{ to: string; weight: number }>> = new Map();
    for (const n of nodes) {
        adj.set(n, []);
    }
    for (const e of edges) {
        adj.get(e.from)!.push({ to: e.to, weight: e.weight });
        adj.get(e.to)!.push({ to: e.from, weight: e.weight });
    }

    // Dijkstra's algorithm from source "A"
    const dist: Map<string, number> = new Map();
    for (const n of nodes) {
        dist.set(n, Infinity);
    }
    dist.set('A', 0);

    const visited: Set<string> = new Set();

    while (visited.size < nodes.length) {
        // Find the unvisited node with the smallest tentative distance
        let u: string | null = null;
        let best = Infinity;
        for (const n of nodes) {
            if (!visited.has(n)) {
                const d = dist.get(n)!;
                if (d < best) {
                    best = d;
                    u = n;
                }
            }
        }
        if (u === null) break;

        visited.add(u);

        // Relax all edges from u
        const neighbors = adj.get(u)!;
        for (const { to, weight } of neighbors) {
            if (!visited.has(to)) {
                const alt = dist.get(u)! + weight;
                if (alt < dist.get(to)!) {
                    dist.set(to, alt);
                }
            }
        }
    }

    // Output
    const sorted = [...nodes].sort();
    const lines: string[] = [];
    lines.push('=== Shortest Paths from A ===');
    lines.push('');
    for (const n of sorted) {
        const d = dist.get(n)!;
        lines.push(`A -> ${n}: ${d}`);
    }
    process.stdout.write(lines.join('\n') + '\n');
}

main();

