#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char level[64];
    int count;
} LevelCount;

typedef struct {
    char component[256];
    int error_count;
} ComponentError;

static int cmp_level(const void *a, const void *b) {
    return strcmp(((const LevelCount *)a)->level, ((const LevelCount *)b)->level);
}

static int cmp_msg(const void *a, const void *b) {
    return strcmp(*(const char *const *)a, *(const char *const *)b);
}

int main(void) {
    const char *path = "<tmp>";
    FILE *fp = fopen(path, "r");
    if (!fp) {
        perror("fopen");
        return 1;
    }

    LevelCount *levels = NULL;
    int n_levels = 0;

    ComponentError *components = NULL;
    int n_components = 0;

    char **error_msgs = NULL;
    int n_error_msgs = 0;

    int *hour_counts = (int *)calloc(24, sizeof(int));
    if (!hour_counts) { fclose(fp); return 1; }

    char *line = (char *)malloc(8192);
    if (!line) { free(hour_counts); fclose(fp); return 1; }

    while (fgets(line, 8192, fp)) {
        if (line[0] != '[') continue;

        int hour = (line[12] - '0') * 10 + (line[13] - '0');
        if (hour < 0 || hour > 23) continue;
        hour_counts[hour]++;

        char *p = strchr(line, ']');
        if (!p) continue;
        p++;

        while (*p == ' ') p++;
        char *level_start = p;
        while (*p && *p != ' ') p++;
        int level_len = (int)(p - level_start);
        if (level_len <= 0) continue;
        if (*p == ' ') p++;

        if (*p != '(') continue;
        p++;
        char *comp_start = p;
        while (*p && *p != ')') p++;
        int comp_len = (int)(p - comp_start);
        if (comp_len <= 0) continue;
        if (*p == ')') p++;

        while (*p == ' ') p++;
        if (*p != '-') continue;
        p++;
        while (*p == ' ') p++;

        char *msg = p;
        char *nl = strchr(msg, '\n');
        if (nl) *nl = '\0';
        nl = strchr(msg, '\r');
        if (nl) *nl = '\0';

        /* Store level */
        int found = 0;
        for (int i = 0; i < n_levels; i++) {
            if ((int)strlen(levels[i].level) == level_len &&
                strncmp(levels[i].level, level_start, level_len) == 0) {
                levels[i].count++;
                found = 1;
                break;
            }
        }
        if (!found) {
            levels = (LevelCount *)realloc(levels, (n_levels + 1) * sizeof(LevelCount));
            if (!levels) { fclose(fp); return 1; }
            memcpy(levels[n_levels].level, level_start, level_len);
            levels[n_levels].level[level_len] = '\0';
            levels[n_levels].count = 1;
            n_levels++;
        }

        /* If ERROR, track component and message */
        if (level_len == 5 && strncmp(level_start, "ERROR", 5) == 0) {
            found = 0;
            for (int i = 0; i < n_components; i++) {
                if ((int)strlen(components[i].component) == comp_len &&
                    strncmp(components[i].component, comp_start, comp_len) == 0) {
                    components[i].error_count++;
                    found = 1;
                    break;
                }
            }
            if (!found) {
                components = (ComponentError *)realloc(components, (n_components + 1) * sizeof(ComponentError));
                if (!components) { fclose(fp); return 1; }
                memcpy(components[n_components].component, comp_start, comp_len);
                components[n_components].component[comp_len] = '\0';
                components[n_components].error_count = 1;
                n_components++;
            }

            found = 0;
            for (int i = 0; i < n_error_msgs; i++) {
                if (strcmp(error_msgs[i], msg) == 0) {
                    found = 1;
                    break;
                }
            }
            if (!found) {
                error_msgs = (char **)realloc(error_msgs, (n_error_msgs + 1) * sizeof(char *));
                if (!error_msgs) { fclose(fp); return 1; }
                error_msgs[n_error_msgs] = (char *)malloc(strlen(msg) + 1);
                if (!error_msgs[n_error_msgs]) { fclose(fp); return 1; }
                strcpy(error_msgs[n_error_msgs], msg);
                n_error_msgs++;
            }
        }
    }

    fclose(fp);
    free(line);

    if (n_levels > 0)
        qsort(levels, n_levels, sizeof(LevelCount), cmp_level);
    if (n_error_msgs > 0)
        qsort(error_msgs, n_error_msgs, sizeof(char *), cmp_msg);

    int best_comp = -1;
