import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        StringBuilder sb = new StringBuilder();
        try (BufferedReader br = new BufferedReader(new FileReader(
                "<tmp>"))) {
            char[] buf = new char[4096];
            int n;
            while ((n = br.read(buf)) != -1) {
                sb.append(buf, 0, n);
            }
        }
        String json = sb.toString();

        // Parse nodes
        List<String> nodes = new ArrayList<>();
        int nodesKey = json.indexOf("\"nodes\"");
        int bStart = json.indexOf('[', nodesKey);
        int bEnd = json.indexOf(']', bStart);
        String nodesStr = json.substring(bStart + 1, bEnd);
        int i = 0;
        while (i < nodesStr.length()) {
            if (nodesStr.charAt(i) == '"') {
                int e = nodesStr.indexOf('"', i + 1);
                nodes.add(nodesStr.substring(i + 1, e));
                i = e + 1;
            } else {
                i++;
            }
        }

        // Parse edges
        List<String[]> edges = new ArrayList<>();
        int edgesKey = json.indexOf("\"edges\"");
        int eBStart = json.indexOf('[', edgesKey);
        int depth = 0, eBEnd = -1;
        for (int j = eBStart; j < json.length(); j++) {
            if (json.charAt(j) == '[') depth++;
            else if (json.charAt(j) == ']') {
                depth--;
                if (depth == 0) { eBEnd = j; break; }
            }
        }
        String edgesStr = json.substring(eBStart + 1, eBEnd);
        int k = 0;
        while (k < edgesStr.length()) {
            int oS = edgesStr.indexOf('{', k);
            if (oS == -1) break;
            int oE = edgesStr.indexOf('}', oS);
            String obj = edgesStr.substring(oS, oE + 1);
            String from = extractStr(obj, "from");
            String to = extractStr(obj, "to");
            int weight = extractInt(obj, "weight");
            edges.add(new String[]{from, to, String.valueOf(weight)});
            k = oE + 1;
        }

        // Build adjacency list (undirected)
        Map<String, List<String[]>> adj = new HashMap<>();
        for (String node : nodes) adj.put(node, new ArrayList<>());
        for (String[] edge : edges) {
            adj.get(edge[0]).add(new String[]{edge[1], edge[2]});
            adj.get(edge[1]).add(new String[]{edge[0], edge[2]});
        }

        // Dijkstra's algorithm from "A"
        Map<String, Integer> dist = new HashMap<>();
        for (String node : nodes) dist.put(node, Integer.MAX_VALUE);
        dist.put("A", 0);

        PriorityQueue<Object[]> pq = new PriorityQueue<>((a, b) -> (Integer) a[1] - (Integer) b[1]);
        pq.add(new Object[]{"A", 0});
        Set<String> visited = new HashSet<>();

        while (!pq.isEmpty()) {
            Object[] curr = pq.poll();
            String u = (String) curr[0];
            int d = (Integer) curr[1];
            if (visited.contains(u)) continue;
            visited.add(u);
            for (String[] nb : adj.get(u)) {
                String v = nb[0];
                int w = Integer.parseInt(nb[1]);
                if (!visited.contains(v)) {
                    int nd = d + w;
                    if (nd < dist.get(v)) {
                        dist.put(v, nd);
                        pq.add(new Object[]{v, nd});
                    }
                }
            }
        }

        // Output
        List<String> sorted = new ArrayList<>(nodes);
        Collections.sort(sorted);
        System.out.println("=== Shortest Paths from A ===");
        System.out.println();
        for (String node : sorted) {
            int d = dist.get(node);
            if (d == Integer.MAX_VALUE) {
                System.out.println("A -> " + node + ": unreachable");
            } else {
                System.out.println("A -> " + node + ": " + d);
            }
        }
    }

    static String extractStr(String obj, String key) {
        int idx = obj.indexOf("\"" + key + "\"");
        int colon = obj.indexOf(':', idx);
        int qs = obj.indexOf('"', colon);
        int qe = obj.indexOf('"', qs + 1);
        return obj.substring(qs + 1, qe);
    }

    static int extractInt(String obj, String key) {
        int idx = obj.indexOf("\"" + key + "\"");
        int colon = obj.indexOf(':', idx);
        int s = colon + 1;
        while (s < obj.length() && obj.charAt(s) == ' ') s++;
        int e = s;
        while (e < obj.length() && (Character.isDigit(obj.charAt(e)) || obj.charAt(e) == '-')) e++;
        return Integer.parseInt(obj.substring(s, e));
    }
