use std::fs;
use std::collections::HashMap;

fn skip_whitespace(s: &str, pos: &mut usize) {
    while *pos < s.len() && s.as_bytes()[*pos].is_ascii_whitespace() {
        *pos += 1;
    }
}

fn parse_string(s: &str, pos: &mut usize) -> String {
    // pos should be at opening quote
    *pos += 1; // skip opening "
    let mut result = String::new();
    while *pos < s.len() {
        let c = s.as_bytes()[*pos] as char;
        if c == '\\' {
            *pos += 1;
            let esc = s.as_bytes()[*pos] as char;
            match esc {
                '"' => result.push('"'),
                '\\' => result.push('\\'),
                'n' => result.push('\n'),
                't' => result.push('\t'),
                'r' => result.push('\r'),
                other => result.push(other),
            }
            *pos += 1;
        } else if c == '"' {
            *pos += 1;
            break;
        } else {
            result.push(c);
            *pos += 1;
        }
    }
    result
}

fn parse_number(s: &str, pos: &mut usize) -> f64 {
    let start = *pos;
    while *pos < s.len() {
        let c = s.as_bytes()[*pos];
        if c.is_ascii_digit() || c == b'-' || c == b'+' || c == b'.' || c == b'e' || c == b'E' {
            *pos += 1;
        } else {
            break;
        }
    }
    s[start..*pos].parse::<f64>().unwrap()
}

fn parse_string_array(s: &str, pos: &mut usize) -> Vec<String> {
    // pos should be at '['
    *pos += 1;
    let mut result = Vec::new();
    skip_whitespace(s, pos);
    if *pos < s.len() && s.as_bytes()[*pos] == b']' {
        *pos += 1;
        return result;
    }
    loop {
        skip_whitespace(s, pos);
        if *pos < s.len() && s.as_bytes()[*pos] == b'"' {
            let str_val = parse_string(s, pos);
            result.push(str_val);
        }
        skip_whitespace(s, pos);
        if *pos < s.len() && s.as_bytes()[*pos] == b',' {
            *pos += 1;
        } else if *pos < s.len() && s.as_bytes()[*pos] == b']' {
            *pos += 1;
            break;
        } else {
            break;
        }
    }
    result
}

struct Edge {
    from: String,
    to: String,
    weight: f64,
}

fn parse_edges(s: &str, pos: &mut usize) -> Vec<Edge> {
    // pos should be at '['
    *pos += 1;
    let mut result = Vec::new();
    skip_whitespace(s, pos);
    if *pos < s.len() && s.as_bytes()[*pos] == b']' {
        *pos += 1;
        return result;
    }
    loop {
        skip_whitespace(s, pos);
        if *pos >= s.len() || s.as_bytes()[*pos] == b']' {
            if *pos < s.len() {
                *pos += 1;
            }
            break;
        }
        // parse object {
        if s.as_bytes()[*pos] == b'{' {
            *pos += 1;
        }
        let mut from = String::new();
        let mut to = String::new();
        let mut weight = 0.0;
        loop {
            skip_whitespace(s, pos);
            if *pos >= s.len() {
                break;
            }
            if s.as_bytes()[*pos] == b'}' {
                *pos += 1;
                break;
            }
            if s.as_bytes()[*pos] == b',' {
                *pos += 1;
                continue;
            }
            // parse key
            let key = parse_string(s, pos);
            skip_whitespace(s, pos);
            // expect ':'
            if *pos < s.len() && s.as_bytes()[*pos] == b':' {
                *pos += 1;
            }
            skip_whitespace(s, pos);
            // parse value
            if *pos < s.len() && s.as_bytes()[*pos] == b'"' {
                let val = parse_string(s, pos);
                if key == "from" {
                    from = val;
                } else if key == "to" {
                    to = val;
                }
            } else {
                let val = parse_number(s, pos);
                if key == "weight" {
                    weight = val;
                }
            }
        }
        result.push(Edge { from, to, weight });
        skip_whitespace(s, pos);
        if *pos < s.len() && s.as_bytes()[*pos] == b',' {
            *pos += 1;
        } else if *pos < s.len() && s.as_bytes()[*pos] == b']' {
            *pos += 1;
            break;
        } else {
            break;
        }
    }
    result
}

fn main() {
    let content = fs::read_to_string("<tmp>")
        .expect("Failed to read graph.json");

    let mut pos = 0;
    skip_whitespace(&content, &mut pos);
    // expect '{'
    if content.as_bytes()[pos] == b'{' {
        pos += 1;
    }

    let mut nodes: Vec<String> = Vec::new();
    let mut edges: Vec<Edge> = Vec::new();

    loop {
        skip_whitespace(&content, &mut pos);
        if pos >= content.len() {
            break;
        }
        if content.as_bytes()[pos] == b'}' {
            pos += 1;
            break;
        }
        if content.as_bytes()[pos] == b',' {
            pos += 1;
            continue;
        }
        let key = parse_string(&content, &mut pos);
        skip_whitespace(&content, &mut pos);
        if pos < content.len() && content.as_bytes()[pos] == b':' {
            pos += 1;
        }
        skip_whitespace(&content, &mut pos);
        if key == "nodes" {
            nodes = parse_string_array(&content, &mut pos);
        } else if key == "edges" {
            edges = parse_edges(&content, &mut pos);
        }
    }

    // Build adjacency list
    let mut node_index: HashMap<String, usize> = HashMap::new();
    for (i, n) in nodes.iter().enumerate() {
        node_index.insert(n.clone(), i);
    }

    let n = nodes.len();
    let mut adj: Vec<Vec<(usize, f64)>> = vec![vec![]; n];

    for e in &edges {
        let fi = node_index[&e.from];
        let ti = node_index[&e.to];
        adj[fi].push((ti, e.weight));
        adj[ti].push((fi, e.weight));
    }

    // Dijkstra from "A"
    let start = node_index["A"];
    let mut dist: Vec<f64> = vec![f64::INFINITY; n];
    let mut visited: Vec<bool> = vec![false; n];
    dist[start] = 0.0;

    for _ in 0..n {
        let mut min_idx: Option<usize> = None;
        let mut min_val = f64::INFINITY;
        for i in 0..n {
            if !visited[i] && dist[i] < min_val {
                min_val = dist[i];
                min_idx = Some(i);
            }
        }
        let u = match min_idx {
            Some(i) => i,
            None => break,
        };
        visited[u] = true;

        for &(v, w) in &adj[u] {
            if !visited[v] && dist[u] + w < dist[v] {
                dist[v] = dist[u] + w;
            }
        }
    }

    // Output
    println!("=== Shortest Paths from A ===");
    println!();

    let mut sorted: Vec<(String, f64)> = nodes.iter().zip(dist.iter()).map(|(nm, d)| (nm.clone(), *d)).collect();
    sorted.sort_by(|a, b| a.0.cmp(&b.0));

    for (name, d) in &sorted {
        if *d == f64::INFINITY {
            println!("A -> {}: unreachable", name);
        } else if d.fract() == 0.0 {
            println!("A -> {}: {}", name, *d as i64);
        } else {
            println!("A -> {}: {}", name, d);
        }
    }
}

