import Foundation

let baseDir = "<tmp>"

struct FileInfo {
    let relativePath: String
    let lines: Int
    let chars: Int
}

var files: [String: [FileInfo]] = [:]
var visitedDirs: Set<String> = []

func isSymlink(_ path: String) -> Bool {
    let attrs = try? FileManager.default.attributesOfItem(atPath: path)
    if let type = attrs?[.type] as? FileAttributeType {
        return type == .typeSymbolicLink
    }
    return false
}

func countLines(_ data: Data) -> Int {
    if data.isEmpty { return 0 }
    var count = 0
    for byte in data {
        if byte == 0x0A { count += 1 }
    }
    if let last = data.last, last != 0x0A {
        count += 1
    }
    return count
}

func getExtension(_ name: String) -> String {
    guard let lastDot = name.lastIndex(of: "."), lastDot > name.startIndex else {
        return ""
    }
    return String(name[lastDot...])
}

func walkDirectory(_ path: String) {
    let fm = FileManager.default
    guard let contents = try? fm.contentsOfDirectory(atPath: path) else { return }

    for name in contents {
        let fullPath = path + "/" + name

        if isSymlink(fullPath) {
            continue
        }

        var isDir: ObjCBool = false
        guard fm.fileExists(atPath: fullPath, isDirectory: &isDir) else { continue }

        if isDir.boolValue {
            let resolved = (try? URL(fileURLWithPath: fullPath).resolvingSymlinksInPath().standardizedFileURL.path) ?? fullPath
            if visitedDirs.contains(resolved) { continue }
            visitedDirs.insert(resolved)
            walkDirectory(fullPath)
        } else {
            guard let data = fm.contents(atPath: fullPath) else { continue }

            let charCount = data.count
            let lineCount = countLines(data)
            let relativePath = String(fullPath.dropFirst(baseDir.count + 1))
            let ext = getExtension(name)

            if files[ext] == nil {
                files[ext] = []
            }
            files[ext]?.append(FileInfo(relativePath: relativePath, lines: lineCount, chars: charCount))
        }
    }
}

