import * as fs from 'fs';
import * as path from 'path';

const rootDir = '<tmp>';

interface FileInfo {
  relativePath: string;
  lines: number;
  chars: number;
}

function countLines(content: Buffer): number {
  if (content.length === 0) return 0;
  let count = 0;
  for (let i = 0; i < content.length; i++) {
    if (content[i] === 0x0a) count++;
  }
  if (content[content.length - 1] !== 0x0a) count++;
  return count;
}

function walkDir(dir: string, root: string, visited: Set<string>): Map<string, FileInfo[]> {
  const result: Map<string, FileInfo[]> = new Map();

  let entries: fs.Dirent[];
  try {
    entries = fs.readdirSync(dir, { withFileTypes: true });
  } catch {
    return result;
  }

  for (const entry of entries) {
    const fullPath = path.join(dir, entry.name);
    const relativePath = path.relative(root, fullPath).split(path.sep).join('/');

    if (entry.isSymbolicLink()) {
      continue;
    }

    if (entry.isDirectory()) {
      let realPath: string;
      try {
        realPath = fs.realpathSync(fullPath);
      } catch {
        continue;
      }
      if (visited.has(realPath)) continue;
      visited.add(realPath);
      const subResult = walkDir(fullPath, root, visited);
      for (const [ext, files] of subResult) {
        if (!result.has(ext)) result.set(ext, []);
        const existing = result.get(ext)!;
        for (const f of files) existing.push(f);
      }
    } else if (entry.isFile()) {
      let content: Buffer;
      try {
        content = fs.readFileSync(fullPath);
      } catch {
        continue;
      }
      const lines = countLines(content);
      const chars = content.length;
      const ext = path.extname(entry.name);
      if (!result.has(ext)) result.set(ext, []);
      result.get(ext)!.push({ relativePath, lines, chars });
    }
  }

  return result;
}

const visited = new Set<string>();
try {
  visited.add(fs.realpathSync(rootDir));
} catch {
  visited.add(rootDir);
}
const fileMap = walkDir(rootDir, rootDir, visited);

