        System.out.print(sb.toString());
    }

    static void walk(Path root, Path dir, Map<String, List<FileEntry>> extMap) throws IOException {
        try (DirectoryStream<Path> stream = Files.newDirectoryStream(dir)) {
            for (Path path : stream) {
                if (Files.isSymbolicLink(path)) continue;
                if (Files.isDirectory(path)) {
                    walk(root, path, extMap);
                } else if (Files.isRegularFile(path)) {
                    long chars = Files.size(path);
                    long lines = countLines(path);

                    String fileName = path.getFileName().toString();
                    String relPath = root.relativize(path).toString().replace('\\', '/');

                    String ext = "";
                    int lastDot = fileName.lastIndexOf('.');
                    if (lastDot > 0) {
                        ext = fileName.substring(lastDot);
                    }

                    extMap.computeIfAbsent(ext, k -> new ArrayList<>()).add(new FileEntry(relPath, lines, chars));
                }
            }
        }
    }

    static long countLines(Path path) throws IOException {
        long lines = 0;
        try (BufferedReader reader = Files.newBufferedReader(path)) {
            while (reader.readLine() != null) {
                lines++;
            }
        }
        return lines;
    }
}

