use std::fs;

#[derive(Debug, Clone)]
enum Value {
    Null,
    Bool(bool),
    Number(f64),
    Str(String),
    Array(Vec<Value>),
    Object(Vec<(String, Value)>),
}

struct Parser {
    chars: Vec<char>,
    pos: usize,
}

impl Parser {
    fn new(s: &str) -> Self {
        Parser { chars: s.chars().collect(), pos: 0 }
    }

    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }

    fn next(&mut self) -> Option<char> {
        let c = self.chars.get(self.pos).copied();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }

    fn skip_whitespace(&mut self) {
        while let Some(c) = self.peek() {
            if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
                self.pos += 1;
            } else {
                break;
            }
        }
    }

    fn expect(&mut self, c: char) {
        self.skip_whitespace();
        let got = self.next().expect("unexpected end of input");
        assert_eq!(got, c, "expected '{}' but got '{}'", c, got);
    }

    fn parse_value(&mut self) -> Value {
        self.skip_whitespace();
        match self.peek() {
            Some('{') => self.parse_object(),
            Some('[') => self.parse_array(),
            Some('"') => Value::Str(self.parse_string()),
            Some('t') => {
                self.parse_literal("true");
                Value::Bool(true)
            }
            Some('f') => {
                self.parse_literal("false");
                Value::Bool(false)
            }
            Some('n') => {
                self.parse_literal("null");
                Value::Null
            }
            _ => self.parse_number(),
        }
    }

    fn parse_literal(&mut self, lit: &str) {
        for c in lit.chars() {
            let got = self.next().unwrap();
            assert_eq!(got, c);
        }
    }

    fn parse_string(&mut self) -> String {
        self.expect('"');
        let mut s = String::new();
        loop {
            let c = self.next().unwrap();
            match c {
                '"' => break,
                '\\' => {
                    let esc = self.next().unwrap();
                    match esc {
                        '"' => s.push('"'),
                        '\\' => s.push('\\'),
                        '/' => s.push('/'),
                        'b' => s.push('\u{0008}'),
                        'f' => s.push('\u{000C}'),
                        'n' => s.push('\n'),
                        'r' => s.push('\r'),
                        't' => s.push('\t'),
                        'u' => {
                            let code = self.parse_hex4();
                            if (0xD800..=0xDBFF).contains(&code) {
                                if self.peek() == Some('\\') {
                                    self.pos += 1;
                                    if self.peek() == Some('u') {
                                        self.pos += 1;
                                        let low = self.parse_hex4();
                                        if (0xDC00..=0xDFFF).contains(&low) {
                                            let cp = 0x10000 + ((code - 0xD800) << 10) + (low - 0xDC00);
                                            s.push(char::from_u32(cp).unwrap());
                                        } else {
                                            s.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                                            // re-process low as separate escape
                                            let _ = low;
                                        }
                                    } else {
                                        s.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                                    }
                                } else {
                                    s.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                                }
                            } else {
                                s.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                            }
                        }
                        _ => panic!("invalid escape character: {}", esc),
                    }
                }
                _ => s.push(c),
            }
        }
        s
    }

    fn parse_hex4(&mut self) -> u32 {
        let mut code = 0u32;
        for _ in 0..4 {
            let h = self.next().unwrap();
            let val = match h {
                '0'..='9' => h as u32 - '0' as u32,
                'a'..='f' => h as u32 - 'a' as u32 + 10,
                'A'..='F' => h as u32 - 'A' as u32 + 10,
                _ => panic!("invalid hex digit: {}", h),
            };
            code = code * 16 + val;
        }
        code
    }

    fn parse_number(&mut self) -> Value {
        let start = self.pos;
        if self.peek() == Some('-') {
            self.pos += 1;
        }
        while let Some(c) = self.peek() {
            if c.is_ascii_digit() || c == '.' || c == 'e' || c == 'E' || c == '+' || c == '-' {
                self.pos += 1;
            } else {
                break;
            }
        }
        let s: String = self.chars[start..self.pos].iter().collect();
        let n: f64 = s.parse().expect(&format!("invalid number: {}", s));
        Value::Number(n)
    }

    fn parse_array(&mut self) -> Value {
        self.expect('[');
        let mut items = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some(']') {
            self.pos += 1;
            return Value::Array(items);
        }
        loop {
            items.push(self.parse_value());
            self.skip_whitespace();
            match self.next().unwrap() {
                ',' => continue,
                ']' => break,
                c => panic!("expected ',' or ']' in array but got '{}'", c),
            }
        }
        Value::Array(items)
    }

    fn parse_object(&mut self) -> Value {
        self.expect('{');
        let mut items = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some('}') {
            self.pos += 1;
            return Value::Object(items);
        }
        loop {
            self.skip_whitespace();
            let key = self.parse_string();
            self.skip_whitespace();
            self.expect(':');
            let val = self.parse_value();
            items.push((key, val));
            self.skip_whitespace();
            match self.next().unwrap() {
                ',' => continue,
                '}' => break,
                c => panic!("expected ',' or '}}' in object but got '{}'", c),
            }
        }
        Value::Object(items)
    }
}

fn value_eq(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Null, Value::Null) => true,
        (Value::Bool(a), Value::Bool(b)) => a == b,
        (Value::Number(a), Value::Number(b)) => a == b,
        (Value::Str(a), Value::Str(b)) => a == b,
        (Value::Array(a), Value::Array(b)) => {
            a.len() == b.len() && a.iter().zip(b.iter()).all(|(x, y)| value_eq(x, y))
        }
        (Value::Object(a), Value::Object(b)) => {
            if a.len() != b.len() {
                return false;
            }
            a.iter().all(|(k, v)| {
                b.iter()
                    .find(|(k2, _)| k2 == k)
                    .map_or(false, |(_, v2)| value_eq(v, v2))
            })
        }
        _ => false,
    }
}

fn deep_merge(a: &Value, b: &Value) -> Value {
    match (a, b) {
        (Value::Object(a_obj), Value::Object(b_obj)) => {
            let mut result: Vec<(String, Value)> = Vec::new();
            for (k, v) in a_obj.iter() {
                result.push((k.clone(), v.clone()));
            }
            let mut i = 0;
            while i < result.len() {
                if let Some(bi) = b_obj.iter().position(|(bk, _)| bk == &result[i].0) {
                    let merged = deep_merge(&result[i].1, &b_obj[bi].1);
                    result[i].1 = merged;
                }
                i += 1;
            }
            for (k, v) in b_obj.iter() {
                if !result.iter().any(|(rk, _)| rk == k) {
                    result.push((k.clone(), v.clone()));
                }
            }
            Value::Object(result)
        }
        (Value::Array(a_arr), Value::Array(b_arr)) => {
            let mut result: Vec<Value> = a_arr.clone();
            for item in b_arr.iter() {
                if !result.iter().any(|x| value_eq(x, item)) {
                    result.push(item.clone());
                }
            }
            Value::Array(result)
        }
        (_, b) => b.clone(),
    }
}

fn escape_string(s: &str) -> String {
    let mut result = String::new();
    for c in s.chars() {
        match c {
            '"' => result.push_str("\\\""),
            '\\' => result.push_str("\\\\"),
            '\n' => result.push_str("\\n"),
            '\r' => result.push_str("\\r"),
            '\t' => result.push_str("\\t"),
            '\u{0008}' => result.push_str("\\b"),
            '\u{000C}' => result.push_str("\\f"),
            c if (c as u32) < 0x20 => {
                result.push_str(&format!("\\u{:04x}", c as u32));
            }
            c => result.push(c),
        }
    }
    result
}

fn format_number(n: f64) -> String {
    if n.fract() == 0.0 && n.abs() < 1e15 {
        format!("{}", n as i64)
    } else {
        format!("{}", n)
    }
}

fn serialize(value: &Value, indent: usize) -> String {
    let pad = "  ".repeat(indent);
    let pad_inner = "  ".repeat(indent + 1);
    match value {
        Value::Null => "null".to_string(),
        Value::Bool(b) => b.to_string(),
        Value::Number(n) => format_number(*n),
        Value::Str(s) => format!("\"{}\"", escape_string(s)),
        Value::Array(arr) => {
            if arr.is_empty() {
                "[]".to_string()
            } else {
                let mut parts = Vec::new();
                for item in arr.iter() {
                    parts.push(format!("{}{}", pad_inner, serialize(item, indent + 1)));
                }
                format!("[\n{}\n{}]", parts.join(",\n"), pad)
            }
        }
        Value::Object(obj) => {
            if obj.is_empty() {
                "{}".to_string()
            } else {
                let mut sorted: Vec<&(String, Value)> = obj.iter().collect();
                sorted.sort_by(|a, b| a.0.cmp(&b.0));
                let mut parts = Vec::new();
                for (k, v) in sorted.iter() {
                    parts.push(format!(
                        "{}\"{}\": {}",
                        pad_inner,
                        escape_string(k),
                        serialize(v, indent + 1)
                    ));
                }
                format!("{{\n{}\n{}}}", parts.join(",\n"), pad)
            }
        }
    }
}

fn main() {
    let a_str = fs::read_to_string(
        "<tmp>",
    )
    .expect("failed to read config_a.json");
    let b_str = fs::read_to_string(
        "<tmp>",
    )
    .expect("failed to read config_b.json");

    let a = Parser::new(&a_str).parse_value();
    let b = Parser::new(&b_str).parse_value();

    let merged = deep_merge(&a, &b);

    print!("{}", serialize(&merged, 0));
}

