struct FileInfo {
    lines: usize,
    chars: usize,
}

fn count_lines_and_chars(path: &Path) -> (usize, usize) {
    let mut contents = Vec::new();
    if let Ok(mut file) = fs::File::open(path) {
        if let Ok(n) = file.read_to_end(&mut contents) {
            let chars = n;
            let lines = if contents.is_empty() {
                0
            } else {
                let newline_count = contents.iter().filter(|&&b| b == b'\n').count();
                if contents[contents.len() - 1] == b'\n' {
                    newline_count
                } else {
                    newline_count + 1
                }
            };
            return (lines, chars);
        }
    }
    (0, 0)
}

fn walk_dir(dir: &Path, base: &Path, files: &mut Vec<(String, FileInfo)>) {
    let entries = match fs::read_dir(dir) {
        Ok(e) => e,
        Err(_) => return,
    };
    for entry in entries {
        let entry = match entry {
            Ok(e) => e,
            Err(_) => continue,
        };
        let ft = match entry.file_type() {
            Ok(t) => t,
            Err(_) => continue,
        };
        if ft.is_symlink() {
            continue;
        }
        let path = entry.path();
        if ft.is_dir() {
            walk_dir(&path, base, files);
        } else if ft.is_file() {
            let rel = path.strip_prefix(base).unwrap_or(&path);
            let rel_str = rel.to_string_lossy().replace('\\', "/");
            let (lines, chars) = count_lines_and_chars(&path);
            files.push((rel_str, FileInfo { lines, chars }));
        }
    }
}

