fn main() {
    let base = Path::new("<tmp>");

    let mut files: Vec<(String, FileInfo)> = Vec::new();
    walk_dir(base, base, &mut files);

    let mut groups: BTreeMap<String, Vec<(String, FileInfo)>> = BTreeMap::new();
    for (rel, info) in files {
        let ext = {
            let p = Path::new(&rel);
            match p.extension() {
                Some(e) => format!(".{}", e.to_string_lossy()),
                None => "(no extension)".to_string(),
            }
        };
        groups.entry(ext).or_default().push((rel, info));
    }

    for v in groups.values_mut() {
        v.sort_by(|a, b| a.0.cmp(&b.0));
    }

    println!("=== File Tree Analysis ===");
    println!();

    let mut total_files = 0usize;
    let mut total_lines = 0usize;
    let mut total_chars = 0usize;

    for (ext, file_list) in &groups {
        let files_count = file_list.len();
        let lines_sum: usize = file_list.iter().map(|f| f.1.lines).sum();
        let chars_sum: usize = file_list.iter().map(|f| f.1.chars).sum();

