use std::io::{Read, Write};
use std::net::TcpStream;

#[derive(Debug, Clone)]
enum Json {
    Null,
    Bool(bool),
    Number(f64),
    Str(String),
    Array(Vec<Json>),
    Object(Vec<(String, Json)>),
}

impl Json {
    fn get(&self, key: &str) -> Option<&Json> {
        if let Json::Object(pairs) = self {
            for (k, v) in pairs {
                if k == key {
                    return Some(v);
                }
            }
        }
        None
    }

    fn as_str(&self) -> Option<&str> {
        if let Json::Str(s) = self {
            Some(s)
        } else {
            None
        }
    }

    fn as_f64(&self) -> Option<f64> {
        if let Json::Number(n) = self {
            Some(*n)
        } else {
            None
        }
    }
}

struct Parser<'a> {
    data: &'a [u8],
    pos: usize,
}

impl<'a> Parser<'a> {
    fn new(s: &'a str) -> Self {
        Parser {
            data: s.as_bytes(),
            pos: 0,
        }
    }

    fn skip_ws(&mut self) {
        while self.pos < self.data.len() {
            let c = self.data[self.pos];
            if c == b' ' || c == b'\t' || c == b'\n' || c == b'\r' {
                self.pos += 1;
            } else {
                break;
            }
        }
    }

    fn peek(&self) -> Option<u8> {
        self.data.get(self.pos).copied()
    }

    fn next_byte(&mut self) -> Option<u8> {
        let b = self.data.get(self.pos).copied();
        if b.is_some() {
            self.pos += 1;
        }
        b
    }

    fn parse_value(&mut self) -> Json {
        self.skip_ws();
        match self.peek() {
            Some(b'[') => self.parse_array(),
            Some(b'{') => self.parse_object(),
            Some(b'"') => Json::Str(self.parse_string()),
            Some(b't') => {
                self.pos += 4;
                Json::Bool(true)
            }
            Some(b'f') => {
                self.pos += 5;
                Json::Bool(false)
            }
            Some(b'n') => {
                self.pos += 4;
                Json::Null
            }
            _ => Json::Number(self.parse_number()),
        }
    }

    fn parse_string(&mut self) -> String {
        self.pos += 1; // skip opening "
        let mut bytes: Vec<u8> = Vec::new();
        loop {
            match self.next_byte() {
                Some(b'"') => break,
                Some(b'\\') => match self.next_byte() {
                    Some(b'"') => bytes.push(b'"'),
                    Some(b'\\') => bytes.push(b'\\'),
                    Some(b'/') => bytes.push(b'/'),
                    Some(b'n') => bytes.push(b'\n'),
                    Some(b'r') => bytes.push(b'\r'),
                    Some(b't') => bytes.push(b'\t'),
                    Some(b'b') => bytes.push(0x08),
                    Some(b'f') => bytes.push(0x0C),
                    Some(b'u') => {
                        let mut code: u32 = 0;
                        for _ in 0..4 {
                            let c = self.next_byte().unwrap() as char;
                            code = code * 16 + c.to_digit(16).unwrap();
                        }
                        if let Some(ch) = char::from_u32(code) {
                            let mut buf = [0u8; 4];
                            bytes.extend_from_slice(ch.encode_utf8(&mut buf).as_bytes());
                        }
                    }
                    _ => {}
                },
                Some(b) => bytes.push(b),
                None => break,
            }
        }
        String::from_utf8(bytes).unwrap()
    }

    fn parse_number(&mut self) -> f64 {
        let start = self.pos;
        if self.peek() == Some(b'-') {
            self.pos += 1;
        }
        while self.pos < self.data.len() {
            let c = self.data[self.pos];
            if c.is_ascii_digit() || c == b'.' || c == b'-' || c == b'+' || c == b'e' || c == b'E'
            {
                self.pos += 1;
            } else {
                break;
            }
        }
        let s = std::str::from_utf8(&self.data[start..self.pos]).unwrap();
        s.parse::<f64>().unwrap()
    }

    fn parse_array(&mut self) -> Json {
        self.pos += 1; // skip [
        let mut arr: Vec<Json> = Vec::new();
        self.skip_ws();
        if self.peek() == Some(b']') {
            self.pos += 1;
            return Json::Array(arr);
        }
        loop {
            arr.push(self.parse_value());
            self.skip_ws();
            match self.next_byte() {
                Some(b',') => continue,
                Some(b']') => break,
                _ => break,
            }
        }
        Json::Array(arr)
    }

    fn parse_object(&mut self) -> Json {
        self.pos += 1; // skip {
        let mut obj: Vec<(String, Json)> = Vec::new();
        self.skip_ws();
        if self.peek() == Some(b'}') {
            self.pos += 1;
            return Json::Object(obj);
        }
        loop {
            self.skip_ws();
            let key = self.parse_string();
            self.skip_ws();
            self.pos += 1; // skip :
            let val = self.parse_value();
            obj.push((key, val));
            self.skip_ws();
            match self.next_byte() {
                Some(b',') => continue,
                Some(b'}') => break,
                _ => break,
            }
        }
        Json::Object(obj)
    }
}

fn dechunk(data: &str) -> String {
    let mut result = String::new();
    let mut remaining = data;
    loop {
        let line_end = match remaining.find('\n') {
            Some(i) => i,
            None => break,
        };
        let size_line = remaining[..line_end].trim_end_matches('\r');
        let size = match usize::from_str_radix(size_line.trim(), 16) {
            Ok(s) => s,
            Err(_) => break,
        };
        if size == 0 {
            break;
        }
        let start = line_end + 1;
        if start + size > remaining.len() {
            break;
        }
        result.push_str(&remaining[start..start + size]);
        remaining = &remaining[start + size..];
        if remaining.starts_with("\r\n") {
            remaining = &remaining[2..];
        } else if remaining.starts_with('\n') {
            remaining = &remaining[1..];
        }
    }
    result
}

fn main() {
    let mut stream = TcpStream::connect("127.0.0.1:18923").expect("Failed to connect");
    let request =
        "GET /api/products HTTP/1.1\r\nHost: 127.0.0.1:18923\r\nConnection: close\r\n\r\n";
    stream
        .write_all(request.as_bytes())
        .expect("Failed to write request");

    let mut response = String::new();
    stream
        .read_to_string(&mut response)
        .expect("Failed to read response");

    // Split headers and body
    let (headers, body_raw) = if let Some(idx) = response.find("\r\n\r\n") {
        (&response[..idx], &response[idx + 4..])
    } else if let Some(idx) = response.find("\n\n") {
        (&response[..idx], &response[idx + 2..])
    } else {
        ("", &response)
    };

    // Handle chunked transfer encoding
    let body = if headers.to_lowercase().contains("transfer-encoding: chunked") {
        dechunk(body_raw)
    } else {
        body_raw.to_string()
    };

    // Parse JSON
    let mut parser = Parser::new(&body);
    let json = parser.parse_value();

    // Extract products (name, price)
    let products: Vec<(String, f64)> = if let Json::Array(arr) = &json {
        arr.iter()
            .filter_map(|item| {
                let name = item.get("name")?.as_str()?.to_string();
                let price = item.get("price")?.as_f64()?;
                Some((name, price))
            })
            .collect()
    } else {
        Vec::new()
    };

    // Filter: price > 50.00
    let filtered: Vec<(String, f64)> = products
