    for (int i = 0; i < num_nodes; i++) {
        int idx = order[i];
        if (dist[idx] == INFINITY) {
            printf("A -> %s: unreachable\n", nodes[idx]);
        } else if (dist[idx] == (double)(long long)dist[idx]) {
            printf("A -> %s: %lld\n", nodes[idx], (long long)dist[idx]);
        } else {
            printf("A -> %s: %g\n", nodes[idx], dist[idx]);
        }
    }

    for (int i = 0; i < num_nodes; i++) free(nodes[i]);
    free(nodes);
    for (int i = 0; i < num_edges; i++) { free(edge_from[i]); free(edge_to[i]); }
    free(edge_from);
    free(edge_to);
    free(edge_wt);
    free(dist);
    free(visited);
    free(order);
