            for (int j = 0; j < b->object.count; j++) {
                if (strcmp(b->object.pairs[j].key, key) == 0) { found = j; break; }
            }
            if (found >= 0) {
                JsonValue *merged = merge_values(aval, b->object.pairs[found].value);
                add_to_object(result, xstrdup(key), merged);
            } else {
                add_to_object(result, xstrdup(key), deep_copy(aval));
