/* Sort object keys in place */
static void sort_object_keys(JsonValue *v) {
    if (v->type != JSON_OBJECT) return;
    int cnt = v->object.count;
    if (cnt <= 1) return;
    /* insertion sort by key */
    for (int i = 1; i < cnt; i++) {
        JsonPair tmp = v->object.pairs[i];
        int j = i - 1;
        while (j >= 0 && strcmp(v->object.pairs[j].key, tmp.key) > 0) {
            v->object.pairs[j+1] = v->object.pairs[j];
            j--;
        }
        v->object.pairs[j+1] = tmp;
    }
    /* recurse */
    for (int i = 0; i < cnt; i++)
        sort_object_keys(v->object.pairs[i].value);
}

