                    unsigned int cp = 0;
                    for (int i = 0; i < 4; i++) {
                        char h = p->src[p->pos + 1 + i];
                        cp <<= 4;
                        if (h >= '0' && h <= '9') cp |= (h - '0');
                        else if (h >= 'a' && h <= 'f') cp |= (h - 'a' + 10);
                        else if (h >= 'A' && h <= 'F') cp |= (h - 'A' + 10);
                        else { fprintf(stderr, "Bad hex\n"); exit(1); }
                    }
                    p->pos += 4;
                    /* encode as UTF-8 */
                    if (cp < 0x80) {
                        if (len + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); }
                        buf[len++] = (char)cp;
                    } else if (cp < 0x800) {
                        if (len + 2 >= cap) { cap *= 2; buf = realloc(buf, cap); }
                        buf[len++] = (char)(0xC0 | (cp >> 6));
                        buf[len++] = (char)(0x80 | (cp & 0x3F));
                    } else {
                        if (len + 3 >= cap) { cap *= 2; buf = realloc(buf, cap); }
                        buf[len++] = (char)(0xE0 | (cp >> 12));
                        buf[len++] = (char)(0x80 | ((cp >> 6) & 0x3F));
                        buf[len++] = (char)(0x80 | (cp & 0x3F));
                    }
                    break;
                }
                default: out = e; break;
            }
            p->pos++;
            if (len + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); }
            buf[len++] = out;
        } else {
            if (len + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); }
            buf[len++] = c;
            p->pos++;
        }
    }
    if (p->pos < p->len) p->pos++; /* skip closing quote */
    if (len >= cap) { cap = len + 1; buf = realloc(buf, cap); }
    buf[len] = '\0';
    return buf;
}

static JsonValue *new_value(JsonType t) {
    JsonValue *v = xmalloc(sizeof(JsonValue));
    v->type = t;
    memset(&v->bool_val, 0, sizeof(v->bool_val));
    return v;
}

static JsonValue *parse_value(Parser *p) {
    skip_ws(p);
    if (p->pos >= p->len) { fprintf(stderr, "Unexpected end\n"); exit(1); }
    char c = p->src[p->pos];
    if (c == '{') return parse_object(p);
    if (c == '[') return parse_array(p);
    if (c == '"') {
        JsonValue *v = new_value(JSON_STRING);
        v->string_val = parse_string_raw(p);
        return v;
    }
    if (c == 't') {
        if (p->pos + 3 <= p->len && strncmp(p->src + p->pos, "true", 4) == 0) {
            p->pos += 4;
            JsonValue *v = new_value(JSON_BOOL);
            v->bool_val = 1;
            return v;
        }
        fprintf(stderr, "Bad token\n"); exit(1);
    }
    if (c == 'f') {
        if (p->pos + 4 <= p->len && strncmp(p->src + p->pos, "false", 5) == 0) {
            p->pos += 5;
            JsonValue *v = new_value(JSON_BOOL);
            v->bool_val = 0;
            return v;
        }
        fprintf(stderr, "Bad token\n"); exit(1);
    }
    if (c == 'n') {
        if (p->pos + 3 <= p->len && strncmp(p->src + p->pos, "null", 4) == 0) {
            p->pos += 4;
            return new_value(JSON_NULL);
        }
        fprintf(stderr, "Bad token\n"); exit(1);
    }
    /* number */
    size_t start = p->pos;
    if (c == '-' || c == '+') p->pos++;
    while (p->pos < p->len && ((p->src[p->pos] >= '0' && p->src[p->pos] <= '9') ||
           p->src[p->pos] == '.' || p->src[p->pos] == 'e' || p->src[p->pos] == 'E' ||
           p->src[p->pos] == '+' || p->src[p->pos] == '-')) {
        p->pos++;
    }
    char tmp[64];
    size_t n = p->pos - start;
    if (n >= sizeof(tmp)) n = sizeof(tmp) - 1;
    memcpy(tmp, p->src + start, n);
    tmp[n] = '\0';
    JsonValue *v = new_value(JSON_NUMBER);
    v->number_val = strtod(tmp, NULL);
    return v;
}

static JsonValue *parse_array(Parser *p) {
    p->pos++; /* skip [ */
    JsonValue *v = new_value(JSON_ARRAY);
    v->array.cap = 8;
    v->array.count = 0;
    v->array.items = xmalloc(sizeof(JsonValue *) * v->array.cap);
    skip_ws(p);
    if (p->pos < p->len && p->src[p->pos] == ']') { p->pos++; return v; }
    while (1) {
        skip_ws(p);
        JsonValue *item = parse_value(p);
        if (v->array.count >= v->array.cap) {
            v->array.cap *= 2;
            v->array.items = realloc(v->array.items, sizeof(JsonValue *) * v->array.cap);
        }
        v->array.items[v->array.count++] = item;
        skip_ws(p);
        if (p->pos < p->len && p->src[p->pos] == ',') { p->pos++; continue; }
        if (p->pos < p->len && p->src[p->pos] == ']') { p->pos++; break; }
        fprintf(stderr, "Expected , or ] in array\n"); exit(1);
    }
    return v;
}

static JsonValue *parse_object(Parser *p) {
    p->pos++; /* skip { */
    JsonValue *v = new_value(JSON_OBJECT);
    v->object.cap = 8;
    v->object.count = 0;
    v->object.pairs = xmalloc(sizeof(JsonPair) * v->object.cap);
    skip_ws(p);
    if (p->pos < p->len && p->src[p->pos] == '}') { p->pos++; return v; }
    while (1) {
        skip_ws(p);
        char *key = parse_string_raw(p);
        skip_ws(p);
        if (p->pos >= p->len || p->src[p->pos] != ':') { fprintf(stderr, "Expected :\n"); exit(1); }
        p->pos++;
        skip_ws(p);
        JsonValue *val = parse_value(p);
        if (v->object.count >= v->object.cap) {
            v->object.cap *= 2;
            v->object.pairs = realloc(v->object.pairs, sizeof(JsonPair) * v->object.cap);
        }
        v->object.pairs[v->object.count].key = key;
        v->object.pairs[v->object.count].value = val;
        v->object.count++;
        skip_ws(p);
        if (p->pos < p->len && p->src[p->pos] == ',') { p->pos++; continue; }
        if (p->pos < p->len && p->src[p->pos] == '}') { p->pos++; break; }
        fprintf(stderr, "Expected , or } in object\n"); exit(1);
    }
    return v;
}

static char *read_file(const char *path) {
    FILE *f = fopen(path, "rb");
    if (!f) { fprintf(stderr, "Cannot open %s\n", path); exit(1); }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = xmalloc((size_t)sz + 1);
    size_t rd = fread(buf, 1, (size_t)sz, f);
    buf[rd] = '\0';
    fclose(f);
    return buf;
}

static JsonValue *deep_copy(JsonValue *v) {
    if (!v) return NULL;
    JsonValue *nv = new_value(v->type);
    switch (v->type) {
        case JSON_NULL: break;
        case JSON_BOOL: nv->bool_val = v->bool_val; break;
        case JSON_NUMBER: nv->number_val = v->number_val; break;
        case JSON_STRING: nv->string_val = xstrdup(v->string_val); break;
        case JSON_ARRAY:
            nv->array.cap = v->array.count + 1;
            nv->array.count = v->array.count;
            nv->array.items = xmalloc(sizeof(JsonValue *) * nv->array.cap);
            for (int i = 0; i < v->array.count; i++)
                nv->array.items[i] = deep_copy(v->array.items[i]);
            break;
        case JSON_OBJECT:
            nv->object.cap = v->object.count + 1;
            nv->object.count = v->object.count;
            nv->object.pairs = xmalloc(sizeof(JsonPair) * nv->object.cap);
            for (int i = 0; i < v->object.count; i++) {
                nv->object.pairs[i].key = xstrdup(v->object.pairs[i].key);
                nv->object.pairs[i].value = deep_copy(v->object.pairs[i].value);
            }
            break;
    }
    return nv;
}

/* Canonical compact serialization for comparison */
static void canonicalize(JsonValue *v, char **buf, size_t *len, size_t *cap) {
    char tmp[512];
    int n;
    switch (v->type) {
        case JSON_NULL:
            n = snprintf(tmp, sizeof(tmp), "null");
            break;
        case JSON_BOOL:
            n = snprintf(tmp, sizeof(tmp), v->bool_val ? "true" : "false");
            break;
        case JSON_NUMBER: {
            double d = v->number_val;
            if (d == floor(d) && fabs(d) < 1e15)
                n = snprintf(tmp, sizeof(tmp), "%lld", (long long)d);
            else
                n = snprintf(tmp, sizeof(tmp), "%.17g", d);
            break;
        }
        case JSON_STRING: {
            /* escape the string */
            size_t slen = strlen(v->string_val);
            size_t need = slen * 2 + 3;
            char *sbuf = xmalloc(need);
            size_t si = 0;
            sbuf[si++] = '"';
            for (size_t i = 0; i < slen; i++) {
                char c = v->string_val[i];
                switch (c) {
                    case '"': sbuf[si++]='\\'; sbuf[si++]='"'; break;
                    case '\\': sbuf[si++]='\\'; sbuf[si++]='\\'; break;
                    case '\b': sbuf[si++]='\\'; sbuf[si++]='b'; break;
                    case '\f': sbuf[si++]='\\'; sbuf[si++]='f'; break;
                    case '\n': sbuf[si++]='\\'; sbuf[si++]='n'; break;
                    case '\r': sbuf[si++]='\\'; sbuf[si++]='r'; break;
                    case '\t': sbuf[si++]='\\'; sbuf[si++]='t'; break;
                    default: sbuf[si++]=c; break;
                }
            }
            sbuf[si++] = '"';
            sbuf[si] = '\0';
            n = (int)si;
            /* append to buf */
            if (*len + (size_t)n + 1 > *cap) {
                *cap = (*len + (size_t)n + 1) * 2;
                *buf = realloc(*buf, *cap);
            }
            memcpy(*buf + *len, sbuf, (size_t)n);
            *len += (size_t)n;
            free(sbuf);
            return;
        }
        case JSON_ARRAY: {
            n = snprintf(tmp, sizeof(tmp), "[");
            if (*len + (size_t)n + 1 > *cap) { *cap = (*len + (size_t)n + 1) * 2; *buf = realloc(*buf, *cap); }
            memcpy(*buf + *len, tmp, (size_t)n); *len += (size_t)n;
            for (int i = 0; i < v->array.count; i++) {
                if (i > 0) {
                    n = snprintf(tmp, sizeof(tmp), ",");
                    if (*len + (size_t)n + 1 > *cap) { *cap = (*len + (size_t)n + 1) * 2; *buf = realloc(*buf, *cap); }
                    memcpy(*buf + *len, tmp, (size_t)n); *len += (size_t)n;
                }
                canonicalize(v->array.items[i], buf, len, cap);
            }
            n = snprintf(tmp, sizeof(tmp), "]");
            if (*len + (size_t)n + 1 > *cap) { *cap = (*len + (size_t)n + 1) * 2; *buf = realloc(*buf, *cap); }
            memcpy(*buf + *len, tmp, (size_t)n); *len += (size_t)n;
            return;
        }
        case JSON_OBJECT: {
            n = snprintf(tmp, sizeof(tmp), "{");
            if (*len + (size_t)n + 1 > *cap) { *cap = (*len + (size_t)n + 1) * 2; *buf = realloc(*buf, *cap); }
            memcpy(*buf + *len, tmp, (size_t)n); *len += (size_t)n;
            /* sort keys for canonical form */
            int cnt = v->object.count;
            const char **keys = xmalloc(sizeof(const char *) * (cnt > 0 ? cnt : 1));
            for (int i = 0; i < cnt; i++) keys[i] = v->object.pairs[i].key;
            /* simple insertion sort */
            for (int i = 1; i < cnt; i++) {
                const char *kk = keys[i];
                int j = i - 1;
                while (j >= 0 && strcmp(keys[j], kk) > 0) { keys[j+1] = keys[j]; j--; }
                keys[j+1] = kk;
            }
            for (int i = 0; i < cnt; i++) {
                if (i > 0) {
                    n = snprintf(tmp, sizeof(tmp), ",");
                    if (*len + (size_t)n + 1 > *cap) { *cap = (*len + (size_t)n + 1) * 2; *buf = realloc(*buf, *cap); }
                    memcpy(*buf + *len, tmp, (size_t)n); *len += (size_t)n;
                }
                /* key as string */
                size_t klen = strlen(keys[i]);
