};

typedef struct {
    const char *src;
    size_t pos;
    size_t len;
} Parser;

static void *xmalloc(size_t n) {
    void *p = malloc(n);
    if (!p) { fprintf(stderr, "OOM\n"); exit(1); }
    return p;
}

static char *xstrdup(const char *s) {
    size_t l = strlen(s) + 1;
    char *p = xmalloc(l);
    memcpy(p, s, l);
    return p;
}

static void skip_ws(Parser *p) {
    while (p->pos < p->len) {
        char c = p->src[p->pos];
        if (c == ' ' || c == '\t' || c == '\n' || c == '\r') p->pos++;
        else break;
    }
}

static char *parse_string_raw(Parser *p) {
    if (p->src[p->pos] != '"') { fprintf(stderr, "Expected string at %zu\n", p->pos); exit(1); }
    p->pos++;
    size_t cap = 64, len = 0;
    char *buf = xmalloc(cap);
    while (p->pos < p->len && p->src[p->pos] != '"') {
        char c = p->src[p->pos];
        if (c == '\\') {
            p->pos++;
            if (p->pos >= p->len) break;
            char e = p->src[p->pos];
            char out;
            switch (e) {
                case '"': out = '"'; break;
                case '\\': out = '\\'; break;
                case '/': out = '/'; break;
                case 'b': out = '\b'; break;
                case 'f': out = '\f'; break;
                case 'n': out = '\n'; break;
                case 'r': out = '\r'; break;
                case 't': out = '\t'; break;
                case 'u': {
                    if (p->pos + 4 >= p->len) { fprintf(stderr, "Bad \\u\n"); exit(1); }
                    unsigned int cp = 0;
                    for (int i = 0; i < 4; i++) {
                        char h = p->src[p->pos + 1 + i];
                        cp <<= 4;
                        if (h >= '0' && h <= '9') cp |= (h - '0');
                        else if (h >= 'a' && h <= 'f') cp |= (h - 'a' + 10);
                        else if (h >= 'A' && h <= 'F') cp |= (h - 'A' + 10);
                        else { fprintf(stderr, "Bad hex\n"); exit(1); }
                    }
                    p->pos += 4;
                    if (cp < 0x80) {
                        if (len + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); }
                        buf[len++] = (char)cp;
                    } else if (cp < 0x800) {
                        if (len + 2 >= cap) { cap *= 2; buf = realloc(buf, cap); }
                        buf[len++] = (char)(0xC0 | (cp >> 6));
                        buf[len++] = (char)(0x80 | (cp & 0x3F));
                    } else {
                        if (len + 3 >= cap) { cap *= 2; buf = realloc(buf, cap); }
                        buf[len++] = (char)(0xE0 | (cp >> 12));
                        buf[len++] = (char)(0x80 | ((cp >> 6) & 0x3F));
                        buf[len++] = (char)(0x80 | (cp & 0x3F));
                    }
                    break;
                }
                default: out = e; break;
            }
            p->pos++;
            if (len + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); }
            buf[len++] = out;
        } else {
            if (len + 1 >= cap) { cap *= 2; buf = realloc(buf, cap); }
            buf[len++] = c;
            p->pos++;
        }
    }
    if (p->pos < p->len) p->pos++;
    if (len >= cap) { cap = len + 1; buf = realloc(buf, cap); }
    buf[len] = '\0';
    return buf;
}

static JsonValue *new_value(JsonType t) {
    JsonValue *v = xmalloc(sizeof(JsonValue));
    v->type = t;
    memset(&v->bool_val, 0, sizeof(v->bool_val));
    return v;
}

static JsonValue *parse_object(Parser *p);
static JsonValue *parse_array(Parser *p);
static JsonValue *parse_value(Parser *p);

static JsonValue *parse_value(Parser *p) {
    skip_ws(p);
    if (p->pos >= p->len) { fprintf(stderr, "Unexpected end\n"); exit(1); }
    char c = p->src[p->pos];
    if (c == '{') return parse_object(p);
    if (c == '[') return parse_array(p);
    if (c == '"') {
        JsonValue *v = new_value(JSON_STRING);
        v->string_val = parse_string_raw(p);
        return v;
    }
    if (c == 't') {
        if (p->pos + 4 <= p->len && strncmp(p->src + p->pos, "true", 4) == 0) {
            p->pos += 4;
            JsonValue *v = new_value(JSON_BOOL);
            v->bool_val = 1;
            return v;
        }
        fprintf(stderr, "Bad token\n"); exit(1);
    }
    if (c == 'f') {
        if (p->pos + 5 <= p->len && strncmp(p->src + p->pos, "false", 5) == 0) {
            p->pos += 5;
            JsonValue *v = new_value(JSON_BOOL);
            v->bool_val = 0;
            return v;
        }
        fprintf(stderr, "Bad token\n"); exit(1);
    }
    if (c == 'n') {
        if (p->pos + 4 <= p->len && strncmp(p->src + p->pos, "null", 4) == 0) {
            p->pos += 4;
            return new_value(JSON_NULL);
        }
        fprintf(stderr, "Bad token\n"); exit(1);
    }
    size_t start = p->pos;
    if (c == '-' || c == '+') p->pos++;
    while (p->pos < p->len && ((p->src[p->pos] >= '0' && p->src[p->pos] <= '9') ||
           p->src[p->pos] == '.' || p->src[p->pos] == 'e' || p->src[p->pos] == 'E' ||
           p->src[p->pos] == '+' || p->src[p->pos] == '-')) {
        p->pos++;
    }
    char tmp[64];
    size_t n = p->pos - start;
    if (n >= sizeof(tmp)) n = sizeof(tmp) - 1;
    memcpy(tmp, p->src + start, n);
    tmp[n] = '\0';
    JsonValue *v = new_value(JSON_NUMBER);
    v->number_val = strtod(tmp, NULL);
    return v;
}

static JsonValue *parse_array(Parser *p) {
    p->pos++;
    JsonValue *v = new_value(JSON_ARRAY);
    v->array.cap = 8;
    v->array.count = 0;
    v->array.items = xmalloc(sizeof(JsonValue *) * v->array.cap);
    skip_ws(p);
    if (p->pos < p->len && p->src[p->pos] == ']') { p->pos++; return v; }
    while (1) {
        skip_ws(p);
        JsonValue *item = parse_value(p);
        if (v->array.count >= v->array.cap) {
            v->array.cap *= 2;
            v->array.items = realloc(v->array.items, sizeof(JsonValue *) * v->array.cap);
        }
        v->array.items[v->array.count++] = item;
        skip_ws(p);
        if (p->pos < p->len && p->src[p->pos] == ',') { p->pos++; continue; }
        if (p->pos < p->len && p->src[p->pos] == ']') { p->pos++; break; }
        fprintf(stderr, "Expected , or ] in array\n"); exit(1);
    }
    return v;
}

static JsonValue *parse_object(Parser *p) {
    p->pos++;
    JsonValue *v = new_value(JSON_OBJECT);
    v->object.cap = 8;
    v->object.count = 0;
    v->object.pairs = xmalloc(sizeof(JsonPair) * v->object.cap);
    skip_ws(p);
    if (p->pos < p->len && p->src[p->pos] == '}') { p->pos++; return v; }
    while (1) {
        skip_ws(p);
        char *key = parse_string_raw(p);
        skip_ws(p);
        if (p->pos >= p->len || p->src[p->pos] != ':') { fprintf(stderr, "Expected :\n"); exit(1); }
        p->pos++;
        skip_ws(p);
        JsonValue *val = parse_value(p);
        if (v->object.count >= v->object.cap) {
            v->object.cap *= 2;
            v->object.pairs = realloc(v->object.pairs, sizeof(JsonPair) * v->object.cap);
        }
        v->object.pairs[v->object.count].key = key;
        v->object.pairs[v->object.count].value = val;
        v->object.count++;
        skip_ws(p);
        if (p->pos < p->len && p->src[p->pos] == ',') { p->pos++; continue; }
        if (p->pos < p->len && p->src[p->pos] == '}') { p->pos++; break; }
        fprintf(stderr, "Expected , or } in object\n"); exit(1);
    }
    return v;
}

static char *read_file(const char *path) {
    FILE *f = fopen(path, "rb");
    if (!f) { fprintf(stderr, "Cannot open %s\n", path); exit(1); }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = xmalloc((size_t)sz + 1);
    size_t rd = fread(buf, 1, (size_t)sz, f);
    buf[rd] = '\0';
    fclose(f);
    return buf;
}

static JsonValue *deep_copy(JsonValue *v) {
    if (!v) return NULL;
    JsonValue *nv = new_value(v->type);
    switch (v->type) {
        case JSON_NULL: break;
        case JSON_BOOL: nv->bool_val = v->bool_val; break;
        case JSON_NUMBER: nv->number_val = v->number_val; break;
        case JSON_STRING: nv->string_val = xstrdup(v->string_val); break;
        case JSON_ARRAY:
            nv->array.cap = v->array.count + 1;
            nv->array.count = v->array.count;
            nv->array.items = xmalloc(sizeof(JsonValue *) * nv->array.cap);
            for (int i = 0; i < v->array.count; i++)
                nv->array.items[i] = deep_copy(v->array.items[i]);
            break;
        case JSON_OBJECT:
            nv->object.cap = v->object.count + 1;
            nv->object.count = v->object.count;
            nv->object.pairs = xmalloc(sizeof(JsonPair) * nv->object.cap);
            for (int i = 0; i < v->object.count; i++) {
                nv->object.pairs[i].key = xstrdup(v->object.pairs[i].key);
                nv->object.pairs[i].value = deep_copy(v->object.pairs[i].value);
            }
            break;
    }
    return nv;
}

static void canonicalize(JsonValue *v, char **buf, size_t *len, size_t *cap) {
    char tmp[512];
    int n;
    switch (v->type) {
        case JSON_NULL:
            n = snprintf(tmp, sizeof(tmp), "null");
            break;
        case JSON_BOOL:
            n = snprintf(tmp, sizeof(tmp), v->bool_val ? "true" : "false");
            break;
        case JSON_NUMBER: {
            double d = v->number_val;
            if (d == floor(d) && fabs(d) < 1e15)
                n = snprintf(tmp, sizeof(tmp), "%lld", (long long)d);
            else
                n = snprintf(tmp, sizeof(tmp), "%.17g", d);
            break;
        }
        case JSON_STRING: {
            size_t slen = strlen(v->string_val);
            size_t need = slen * 2 + 3;
            char *sbuf = xmalloc(need);
            size_t si = 0;
            sbuf[si++] = '"';
            for (size_t i = 0; i < slen; i++) {
                char c = v->string_val[i];
                switch (c) {
                    case '"': sbuf[si++]='\\'; sbuf[si++]='"'; break;
                    case '\\': sbuf[si++]='\\'; sbuf[si++]='\\'; break;
                    case '\b': sbuf[si++]='\\'; sbuf[si++]='b'; break;
                    case '\f': sbuf[si++]='\\'; sbuf[si++]='f'; break;
                    case '\n': sbuf[si++]='\\'; sbuf[si++]='n'; break;
                    case '\r': sbuf[si++]='\\'; sbuf[si++]='r'; break;
                    case '\t': sbuf[si++]='\\'; sbuf[si++]='t'; break;
                    default: sbuf[si++]=c; break;
                }
            }
            sbuf[si++] = '"';
            sbuf[si] = '\0';
            n = (int)si;
            if (*len + (size_t)n + 1 > *cap) {
                *cap = (*len + (size_t)n + 1) * 2;
                *buf = realloc(*buf, *cap);
            }
            memcpy(*buf + *len, sbuf, (size_t)n);
            *len += (size_t)n;
            free(sbuf);
            return;
        }
        case JSON_ARRAY: {
            n = snprintf(tmp, sizeof(tmp), "[");
            if (*len + (size_t)n + 1 > *cap) { *cap = (*len + (size_t)n + 1) * 2; *buf = realloc(*buf, *cap); }
            memcpy(*buf + *len, tmp, (size_t)n); *len += (size_t)n;
            for (int i = 0; i < v->array.count; i++) {
                if (i > 0) {
                    n = snprintf(tmp, sizeof(tmp), ",");
                    if (*len + (size_t)n + 1 > *cap) { *cap = (*len + (size_t)n + 1) * 2; *buf = realloc(*buf, *cap); }
                    memcpy(*buf + *len, tmp, (size_t)n); *len += (size_t)n;
                }
                canonicalize(v->array.items[i], buf, len, cap);
            }
            n = snprintf(tmp, sizeof(tmp), "]");
            if (*len + (size_t)n + 1 > *cap) { *cap = (*len + (size_t)n + 1) * 2; *buf = realloc(*buf, *cap); }
            memcpy(*buf + *len, tmp, (size_t)n); *len += (size_t)n;
            return;
        }
        case JSON_OBJECT: {
            n = snprintf(tmp, sizeof(tmp), "{");
            if (*len + (size_t)n + 1 > *cap) { *cap = (*len + (size_t)n + 1) * 2; *buf = realloc(*buf, *cap); }
            memcpy(*buf + *len, tmp, (size_t)n); *len += (size_t)n;
            int cnt = v->object.count;
            const char **keys = xmalloc(sizeof(const char *) * (cnt > 0 ? cnt : 1));
            for (int i = 0; i < cnt; i++) keys[i] = v->object.pairs[i].key;
            for (int i = 1; i < cnt; i++) {
                const char *kk = keys[i];
                int j = i - 1;
                while (j >= 0 && strcmp(keys[j], kk) > 0) { keys[j+1] = keys[j]; j--; }
                keys[j+1] = kk;
            }
            for (int i = 0; i < cnt; i++) {
                if (i > 0) {
                    n = snprintf(tmp, sizeof(tmp), ",");
                    if (*len + (size_t)n + 1 > *cap) { *cap = (*len + (size_t)n + 1) * 2; *buf = realloc(*buf, *cap); }
                    memcpy(*buf + *len, tmp, (size_t)n); *len += (size_t)n;
                }
                size_t klen = strlen(keys[i]);
                size_t need = klen * 2 + 3;
                char *sbuf = xmalloc(need);
                size_t si = 0;
                sbuf[si++] = '"';
                for (size_t ci = 0; ci < klen; ci++) {
                    char c = keys[i][ci];
                    switch (c) {
                        case '"': sbuf[si++]='\\'; sbuf[si++]='"'; break;
                        case '\\': sbuf[si++]='\\'; sbuf[si++]='\\'; break;
                        case '\b': sbuf[si++]='\\'; sbuf[si++]='b'; break;
                        case '\f': sbuf[si++]='\\'; sbuf[si++]='f'; break;
                        case '\n': sbuf[si++]='\\'; sbuf[si++]='n'; break;
                        case '\r': sbuf[si++]='\\'; sbuf[si++]='r'; break;
                        case '\t': sbuf[si++]='\\'; sbuf[si++]='t'; break;
                        default: sbuf[si++]=c; break;
                    }
                }
                sbuf[si++] = '"';
                sbuf[si] = '\0';
                if (*len + si + 1 > *cap) { *cap = (*len + si + 1) * 2; *buf = realloc(*buf, *cap); }
                memcpy(*buf + *len, sbuf, si); *len += si;
                free(sbuf);
                n = snprintf(tmp, sizeof(tmp), ":");
                if (*len + (size_t)n + 1 > *cap) { *cap = (*len + (size_t)n + 1) * 2; *buf = realloc(*buf, *cap); }
                memcpy(*buf + *len, tmp, (size_t)n); *len += (size_t)n;
                canonicalize(v->object.pairs[i].value, buf, len, cap);
            }
            free(keys);
            n = snprintf(tmp, sizeof(tmp), "}");
            if (*len + (size_t)n + 1 > *cap) { *cap = (*len + (size_t)n + 1) * 2; *buf = realloc(*buf, *cap); }
            memcpy(*buf + *len, tmp, (size_t)n); *len += (size_t)n;
            return;
        }
    }
    if (*len + (size_t)n + 1 > *cap) { *cap = (*len + (size_t)n + 1) * 2; *buf = realloc(*buf, *cap); }
    memcpy(*buf + *len, tmp, (size_t)n);
    *len += (size_t)n;
}

static char *canonical_string(JsonValue *v) {
    char *buf = NULL;
    size_t len = 0, cap = 256;
    buf = xmalloc(cap);
    canonicalize(v, &buf, &len, &cap);
    if (len >= cap) { cap = len + 1; buf = realloc(buf, cap); }
    buf[len] = '\0';
    return buf;
}

static int array_contains(JsonValue *arr, JsonValue *item) {
    char *item_canon = canonical_string(item);
    for (int i = 0; i < arr->array.count; i++) {
        char *other_canon = canonical_string(arr->array.items[i]);
        int eq = (strcmp(item_canon, other_canon) == 0);
        free(other_canon);
        if (eq) { free(item_canon); return 1; }
    }
    free(item_canon);
    return 0;
}

static void add_to_array(JsonValue *arr, JsonValue *item) {
    if (arr->array.count >= arr->array.cap) {
        arr->array.cap *= 2;
        arr->array.items = realloc(arr->array.items, sizeof(JsonValue *) * arr->array.cap);
    }
    arr->array.items[arr->array.count++] = item;
}

static void add_to_object(JsonValue *obj, char *key, JsonValue *val) {
    if (obj->object.count >= obj->object.cap) {
        obj->object.cap *= 2;
        obj->object.pairs = realloc(obj->object.pairs, sizeof(JsonPair) * obj->object.cap);
    }
    obj->object.pairs[obj->object.count].key = key;
    obj->object.pairs[obj->object.count].value = val;
    obj->object.count++;
}

static JsonValue *merge_values(JsonValue *a, JsonValue *b) {
    if (a->type == JSON_OBJECT && b->type == JSON_OBJECT) {
        JsonValue *result = new_value(JSON_OBJECT);
        result->object.cap = a->object.count + b->object.count + 1;
        result->object.count = 0;
        result->object.pairs = xmalloc(sizeof(JsonPair) * result->object.cap);
        for (int i = 0; i < a->object.count; i++) {
            char *key = a->object.pairs[i].key;
            JsonValue *aval = a->object.pairs[i].value;
            int found = -1;
            for (int j = 0; j < b->object.count; j++) {
                if (strcmp(b->object.pairs[j].key, key) == 0) { found = j; break; }
            }
            if (found >= 0) {
                JsonValue *merged = merge_values(aval, b->object.pairs[found].value);
                add_to_object(result, xstrdup(key), merged);
            } else {
                add_to_object(result, xstrdup(key), deep_copy(aval));
            }
        }
        for (int j = 0; j < b->object.count; j++) {
            char *key = b->object.pairs[j].key;
            int found = 0;
            for (int i = 0; i < a->object.count; i++) {
                if (strcmp(a->object.pairs[i].key, key) == 0) { found = 1; break; }
            }
            if (!found) {
                add_to_object(result, xstrdup(key), deep_copy(b->object.pairs[j].value));
            }
        }
        return result;
    }
    if (a->type == JSON_ARRAY && b->type == JSON_ARRAY) {
        JsonValue *result = new_value(JSON_ARRAY);
        result->array.cap = a->array.count + b->array.count + 1;
        result->array.count = 0;
        result->array.items = xmalloc(sizeof(JsonValue *) * result->array.cap);
        for (int i = 0; i < a->array.count; i++)
            add_to_array(result, deep_copy(a->array.items[i]));
        for (int j = 0; j < b->array.count; j++) {
            if (!array_contains(result, b->array.items[j]))
                add_to_array(result, deep_copy(b->array.items[j]));
        }
        return result;
    }
    return deep_copy(b);
}

static void sort_object_keys(JsonValue *v) {
    if (v->type != JSON_OBJECT) return;
    int cnt = v->object.count;
    if (cnt <= 1) return;
    for (int i = 1; i < cnt; i++) {
        JsonPair tmp = v->object.pairs[i];
        int j = i - 1;
        while (j >= 0 && strcmp(v->object.pairs[j].key, tmp.key) > 0) {
            v->object.pairs[j+1] = v->object.pairs[j];
            j--;
        }
        v->object.pairs[j+1] = tmp;
    }
    for (int i = 0; i < cnt; i++)
        sort_object_keys(v->object.pairs[i].value);
}

static void print_escaped_string(const char *s) {
    putchar('"');
    for (size_t i = 0; s[i]; i++) {
        char c = s[i];
        switch (c) {
            case '"': fputs("\\\"", stdout); break;
            case '\\': fputs("\\\\", stdout); break;
            case '\b': fputs("\\b", stdout); break;
            case '\f': fputs("\\f", stdout); break;
            case '\n': fputs("\\n", stdout); break;
            case '\r': fputs("\\r", stdout); break;
            case '\t': fputs("\\t", stdout); break;
            default:
                if ((unsigned char)c < 0x20)
                    printf("\\u%04x", (unsigned char)c);
                else
                    putchar(c);
                break;
        }
    }
    putchar('"');
}

static void print_number(double d) {
    if (d == floor(d) && fabs(d) < 1e15)
        printf("%lld", (long long)d);
    else
        printf("%.17g", d);
}

static void print_value(JsonValue *v, int indent) {
    switch (v->type) {
        case JSON_NULL: fputs("null", stdout); break;
        case JSON_BOOL: fputs(v->bool_val ? "true" : "false", stdout); break;
        case JSON_NUMBER: print_number(v->number_val); break;
        case JSON_STRING: print_escaped_string(v->string_val); break;
        case JSON_ARRAY: {
            if (v->array.count == 0) { fputs("[]", stdout); return; }
            fputs("[\n", stdout);
            for (int i = 0; i < v->array.count; i++) {
                for (int k = 0; k < (indent + 1) * 2; k++) putchar(' ');
                print_value(v->array.items[i], indent + 1);
                if (i < v->array.count - 1) fputs(",\n", stdout);
                else fputs("\n", stdout);
            }
            for (int k = 0; k < indent * 2; k++) putchar(' ');
            fputs("]", stdout);
            break;
        }
        case JSON_OBJECT: {
            if (v->object.count == 0) { fputs("{}", stdout); return; }
            fputs("{\n", stdout);
            for (int i = 0; i < v->object.count; i++) {
                for (int k = 0; k < (indent + 1) * 2; k++) putchar(' ');
                print_escaped_string(v->object.pairs[i].key);
                fputs(": ", stdout);
                print_value(v->object.pairs[i].value, indent + 1);
                if (i < v->object.count - 1) fputs(",\n", stdout);
                else fputs("\n", stdout);
            }
            for (int k = 0; k < indent * 2; k++) putchar(' ');
            fputs("}", stdout);
            break;
        }
    }
}

static void free_value(JsonValue *v) {
    if (!v) return;
    switch (v->type) {
        case JSON_STRING: free(v->string_val); break;
        case JSON_ARRAY:
            for (int i = 0; i < v->array.count; i++) free_value(v->array.items[i]);
            free(v->array.items);
            break;
        case JSON_OBJECT:
            for (int i = 0; i < v->object.count; i++) {
                free(v->object.pairs[i].key);
                free_value(v->object.pairs[i].value);
            }
            free(v->object.pairs);
            break;
        default: break;
    }
    free(v);
}

int main(void) {
    const char *path_a = "<tmp>";
